import { isEqual, isPlainObject } from 'lodash';
import { useCallback, useRef, useSyncExternalStore } from 'react';

import { AppEvents } from '@grafana/data';
import { t } from '@grafana/i18n';
import { type Spec as DashboardV2Spec } from '@grafana/schema/apis/dashboard.grafana.app/v2';
import { appEvents } from 'app/core/app_events';
import { isDashboardV2Spec } from 'app/features/dashboard/api/utils';

import { type DashboardScene } from '../scene/DashboardScene';

import {
  getPendingChangesHistory,
  getScenePendingChangePreview,
  type PendingChangesHistory,
  type PendingChangesHistoryState,
  previewedDashboardUid,
} from './pendingChangePreview';
import { reloadPendingChangesPage } from './pendingChangesPageReload';

/**
 * What an edit changes, against the pending changes as stored: the scene saves defaults the stored
 * spec leaves out (plugin versions, option defaults), which would otherwise show as changes to
 * elements nobody touched.
 */
interface RecordingBaseline {
  /** The scene's save model before the edit. */
  serialized: DashboardV2Spec;
  /** The pending changes as stored, which the edit is recorded onto. */
  stored: DashboardV2Spec;
}

const baselines = new WeakMap<DashboardScene, RecordingBaseline>();

/** Scenes with an edit the plugin failed to record: the next recording retries it. */
const unrecorded = new WeakSet<DashboardScene>();

/**
 * Each scene's recordings, one after another: a request starts once the one before it settled, so
 * the plugin gets them in the order they were made, and the newest one is what it keeps.
 */
const queues = new WeakMap<DashboardScene, Promise<void>>();
/** How many of a scene's recordings haven't settled yet. */
const inFlight = new WeakMap<DashboardScene, number>();
/** Scenes whose pending changes changed under them: their queued recordings would overwrite the newer ones. */
const superseded = new WeakSet<DashboardScene>();
/**
 * How many times each scene was reloaded in place. A recording queued before the scene took newer
 * pending changes in is of the ones they replaced: sent now, it would overwrite them.
 */
const reloads = new WeakMap<DashboardScene, number>();

/**
 * Whether an edit on `scene` hasn't reached the plugin's history: still on its way, or failed. The
 * scene counts as saved from the moment it's sent, so leaving or reloading the page would lose it.
 */
export function hasUnrecordedPendingChange(scene: DashboardScene): boolean {
  return unrecorded.has(scene) || (inFlight.get(scene) ?? 0) > 0;
}

/** Settles once every recording of `scene` sent so far has, and never rejects: Undo, Redo and Apply step from there. */
export function pendingChangesRecorded(scene: DashboardScene): Promise<void> {
  return queues.get(scene) ?? Promise.resolve();
}

/**
 * Whether the pending changes `scene` shows changed under one of its recordings: the page then loads
 * the newer ones, which the user hasn't seen, so nothing may act on this scene's behalf any more.
 */
export function pendingChangesSuperseded(scene: DashboardScene): boolean {
  return superseded.has(scene);
}

const ignore = () => {};

/** Starts recording edits to `scene`, which shows the pending changes `stored`, as edit mode starts. */
export function startRecordingPendingChanges(scene: DashboardScene, stored: DashboardV2Spec) {
  // An edit not kept yet, failed or on its way, is in the scene but not in `stored`: a baseline from
  // the two would count it unchanged, and the next recording would leave it out. Keep the one it has.
  if (baselines.has(scene) && hasUnrecordedPendingChange(scene)) {
    return;
  }
  const serialized = scene.getSaveModel();
  if (isDashboardV2Spec(serialized)) {
    baselines.set(scene, { serialized, stored });
  }
}

/**
 * After newer pending changes were reloaded into `scene` in place: it shows them now, so it is no
 * longer superseded, and an edit session records onto them from here, as edit mode starting would.
 * Recordings queued before the reload, and an edit that failed to record, are of the pending changes
 * it replaced: they are dropped.
 */
export function resumeRecordingPendingChanges(scene: DashboardScene) {
  reloads.set(scene, (reloads.get(scene) ?? 0) + 1);
  superseded.delete(scene);
  // An edit that failed to record was of the replaced pending changes too: nothing is left unsaved.
  unrecorded.delete(scene);
  baselines.delete(scene);
  const preview = getScenePendingChangePreview(scene.state);
  if (scene.state.isEditing && preview && getPendingChangesHistory(scene.state)) {
    startRecordingPendingChanges(scene, preview.pending.history?.getState().proposed ?? preview.pending.proposed);
  }
}

/** `stored` with what changed from `before` to `after`: what didn't change keeps its stored form. */
function rebase(stored: unknown, before: unknown, after: unknown): unknown {
  if (isEqual(before, after)) {
    return stored;
  }
  if (!isRecord(stored) || !isRecord(before) || !isRecord(after)) {
    return after;
  }
  const result: Record<string, unknown> = { ...stored };
  for (const key of new Set([...Object.keys(before), ...Object.keys(after)])) {
    if (!(key in after)) {
      delete result[key];
    } else if (!isEqual(before[key], after[key])) {
      result[key] = rebase(stored[key], before[key], after[key]);
    }
  }
  return result;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return isPlainObject(value);
}

/**
 * Edits to pending changes on the dashboard page (see PendingChangesHistory): the dashboard's
 * edit actions, the same ones its Undo steps through, are recorded in the plugin's history
 * instead, so an edit made by hand ends up like one the plugin made. The scene then counts as
 * saved: Exit edit has nothing to save or discard.
 */
export async function recordPendingChange(
  scene: DashboardScene,
  history: PendingChangesHistory,
  description?: string,
  before?: unknown
): Promise<void> {
  const serialized = scene.getSaveModel();
  if (!isDashboardV2Spec(serialized)) {
    return;
  }
  // The scene just before this edit, when known: defaults panels filled in since the last one, as
  // their plugins loaded, then count as unchanged instead of as the edit.
  const baseline = baselines.get(scene);
  const from = isDashboardV2Spec(before) ? before : baseline?.serialized;
  const rebased = baseline && from ? rebase(baseline.stored, from, serialized) : serialized;
  const proposed = isDashboardV2Spec(rebased) ? rebased : serialized;
  baselines.set(scene, { serialized, stored: proposed });
  // Before the request: an edit made while it runs still marks the scene changed.
  scene.markPendingChangesRecorded(serialized);
  // Only defaults the scene filled in changed: nothing to record, unless an earlier edit failed to.
  if (baseline && isEqual(proposed, baseline.stored) && !unrecorded.has(scene)) {
    return;
  }
  inFlight.set(scene, (inFlight.get(scene) ?? 0) + 1);
  const reload = reloads.get(scene) ?? 0;
  const sent = (queues.get(scene) ?? Promise.resolve())
    .then(() => sendRecording(scene, history, proposed, description, reload))
    .finally(() => inFlight.set(scene, (inFlight.get(scene) ?? 1) - 1));
  // The queue goes on past a recording that threw, so the later ones still go out.
  queues.set(scene, sent.then(ignore, ignore));
  await sent;
}

async function sendRecording(
  scene: DashboardScene,
  history: PendingChangesHistory,
  proposed: DashboardV2Spec,
  description: string | undefined,
  reload: number
): Promise<void> {
  // Its pending changes moved on, and the reload to them failed: this edit isn't kept, so leaving warns.
  if (superseded.has(scene)) {
    unrecorded.add(scene);
    return;
  }
  // Made before the scene took newer pending changes in, which the user was told replaced it.
  if ((reloads.get(scene) ?? 0) !== reload) {
    return;
  }
  let recorded: boolean;
  try {
    recorded = (await history.record({ proposed, description })).recorded;
  } catch (error) {
    // The scene took newer pending changes in meanwhile, which replaced this edit.
    if ((reloads.get(scene) ?? 0) !== reload) {
      return;
    }
    // `proposed` stays the baseline, so the next recording, or leaving edit mode, carries this edit.
    unrecorded.add(scene);
    appEvents.emit(AppEvents.alertError, [
      t('dashboard-scene.lifecycle.record-pending-change-failed', 'Your change could not be saved'),
      error instanceof Error ? error.message : String(error),
    ]);
    return;
  }
  // The scene took newer pending changes in while this was on its way: it shows them, whatever this did.
  if ((reloads.get(scene) ?? 0) !== reload) {
    return;
  }
  // Each recording carries the edits before it, so this one kept any that failed.
  unrecorded.delete(scene);
  if (!recorded) {
    superseded.add(scene);
    appEvents.emit(AppEvents.alertWarning, [
      t('dashboard-scene.lifecycle.pending-changes-changed', 'These pending changes changed'),
      t(
        'dashboard-scene.lifecycle.pending-changes-changed-text',
        'Your last change was not saved. Showing the latest pending changes.'
      ),
    ]);
    const uid = previewedDashboardUid(scene.state);
    if (uid) {
      try {
        await reloadKeepingEditMode(uid, scene.state.isEditing);
      } catch {
        // Still on this scene, which stays superseded: Apply, Undo, and Redo would otherwise act on
        // pending changes the page never loaded. Its edit isn't kept, so leaving warns.
        unrecorded.add(scene);
      }
    }
  }
}

/**
 * Loads the dashboard page again, back in edit mode when it was editing, and leaves the requester
 * where they were: into the open scene when it can (true), else onto a new scene.
 */
export function reloadKeepingEditMode(uid: string, editing: boolean | undefined): Promise<boolean> {
  return reloadPendingChangesPage(uid, editing);
}

const noop = () => {};
const noState: PendingChangesHistoryState = {};

/**
 * The pending changes history's state, kept current; empty without a history. The same object while
 * its fields stay the same, as useSyncExternalStore needs, whether or not `getState` returns a new one.
 */
export function usePendingChangesHistoryState(history: PendingChangesHistory | undefined): PendingChangesHistoryState {
  const snapshot = useRef(noState);
  const subscribe = useCallback((listener: () => void) => history?.subscribe(listener) ?? noop, [history]);
  const getSnapshot = useCallback(() => {
    const next = history?.getState() ?? noState;
    const last = snapshot.current;
    if (next.undo !== last.undo || next.redo !== last.redo || next.proposed !== last.proposed) {
      snapshot.current = next;
    }
    return snapshot.current;
  }, [history]);
  return useSyncExternalStore(subscribe, getSnapshot);
}
